/* Thi đua lớp — application bundle (externalized for reliable deployment) */

function showBootError(message){
  const root=document.getElementById("root");
  if(!root)return;
  const safe=String(message||"Ứng dụng gặp lỗi khi khởi động.").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]));
  root.innerHTML=`<div style="min-height:100vh;display:grid;place-items:center;padding:24px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;background:#f5f7fb;color:#0f172a"><div style="width:min(680px,100%);background:#fff;border:1px solid #fecdd3;border-radius:22px;padding:28px;box-shadow:0 18px 55px rgba(15,23,42,.08)"><div style="font-size:12px;font-weight:900;letter-spacing:.06em;color:#dc2626">THI ĐUA LỚP</div><h1 style="margin:8px 0">Không tải được giao diện</h1><p style="margin:0;color:#475569;line-height:1.6">${safe}</p><button onclick="location.reload()" style="margin-top:16px;border:0;border-radius:11px;padding:10px 14px;background:#111827;color:#fff;font-weight:800;cursor:pointer">Tải lại</button></div></div>`;
}
function showFirebaseError(message){
  const root=document.getElementById("root");
  if(!root)return;
  root.innerHTML=`<div style="min-height:100vh;display:grid;place-items:center;padding:24px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;background:#f5f7fb;color:#0f172a"><div style="width:min(680px,100%);background:#fff;border:1px solid #fecdd3;border-radius:22px;padding:28px;box-shadow:0 18px 55px rgba(15,23,42,.08)"><div style="font-size:12px;font-weight:900;letter-spacing:.06em;color:#dc2626">KẾT NỐI FIREBASE</div><h1 style="margin:8px 0">Không thể tải dữ liệu lớp</h1><p style="margin:0;color:#475569;line-height:1.6">${esc(message||"Không thể đọc cấu hình lớp từ Firebase.")}</p><p style="margin:10px 0 0;color:#64748b;line-height:1.6">Dữ liệu cũ không bị xóa. Kiểm tra Firebase Rules, cấu hình Firebase và kết nối mạng, rồi thử lại.</p><button onclick="location.reload()" style="margin-top:16px;border:0;border-radius:11px;padding:10px 14px;background:#111827;color:#fff;font-weight:800;cursor:pointer">Thử lại</button></div></div>`;
}
window.addEventListener("error",e=>{console.error(e.error||e.message);if(!window.__tdBootReady)showBootError("Một thành phần JavaScript bị lỗi khi khởi động. Hãy tải lại trang.")});
window.addEventListener("unhandledrejection",e=>{console.error(e.reason);if(!window.__tdBootReady)showBootError("Một tác vụ khởi động bị lỗi. Hãy tải lại trang.")});

const FIREBASE_CONFIG=window.TD_FIREBASE_CONFIG;
if(!FIREBASE_CONFIG)throw new Error("Không tải được firebase-config.js");
const PATH={config:"classConfig",groups:"groups",students:"students",users:"users",records:"records",reports:"reports",weeks:"weeks",audit:"audit"};
const RULES_MINUS=[["Đi học muộn",-5,"lần"],["Vắng học có phép",-2,"buổi"],["Vắng học không phép",-5,"buổi"],["Tự ý bỏ tiết",-5,"tiết"],["Không thực hiện đúng quy định xin phép khi nghỉ học",-3,"lần"],["Không chuẩn bị sách vở, đồ dùng học tập",-2,"lần"],["Không học bài, không làm bài tập",-2,"lần"],["Không đeo bảng tên đúng quy định",-5,"lần"],["Không gắn/đeo logo trường đúng quy định",-5,"lần"],["Đoàn viên không đeo huy hiệu Đoàn theo quy định",-5,"lần"],["Mặc đồng phục/trang phục không đúng quy định",-5,"lần"],["Bảng tên, logo, huy hiệu không đúng quy định",-5,"lần"],["Cố tình tháo, che giấu hoặc không chấp hành sau khi được nhắc nhở",-10,"lần"],["Nói chuyện, làm việc riêng trong giờ học",-2,"lần"],["Sử dụng điện thoại trong giờ học (trừ trường hợp giáo viên cho phép để phục vụ học tập)",-5,"lần"],["Gây mất trật tự, ảnh hưởng đến lớp",-3,"lần"],["Tập thể dục không nghiêm túc",-5,"lần"],["Trốn tập thể dục",-10,"lần"],["Không thực hiện nghiêm túc hoạt động tập thể",-3,"lần"],["Không thực hiện trực nhật theo phân công",-3,"lần"],["Xả rác, làm mất vệ sinh",-3,"lần"],["Tự ý rời lớp hoặc khu vực quy định",-5,"lần"],["Thiếu lễ phép, thiếu tôn trọng thầy cô, nhân viên nhà trường",-5,"lần"],["Gây gổ, xúc phạm hoặc làm ảnh hưởng đến bạn",null,"lần",5,10],["Cố ý làm hư hỏng bàn ghế, thiết bị hoặc tài sản chung",null,"lần",5,10],["Vi phạm nội quy khác của trường/lớp",null,"theo mức độ"]];
const RULES_PLUS=[["Tích cực giúp đỡ bạn trong học tập",2],["Chủ động thực hiện nhiệm vụ chung của lớp",2],["Có việc làm tốt, được giáo viên ghi nhận",2],["Tích cực tham gia hoạt động của lớp, trường",2],["Có tiến bộ rõ rệt về học tập hoặc ý thức",3],["Có thành tích nổi bật, đóng góp tích cực cho lớp/trường",5]];
const state={fbReady:false,user:null,profile:null,config:null,groups:{},students:{},users:{},records:{},reports:{},weeks:{},audit:{},lastDeleted:null,tab:"home",week:mkWeek(new Date()),group:"all",search:"",setupStep:1,syncError:null,setup:{className:"",schoolYear:"2026–2027",groupCount:4,groups:[],studentsText:"",ltId:"",lpId:"",studentPass:"",gvcnPass:"",ltPass:"",lpPass:"",groupLeaders:{}}};
let fb={app:null,auth:null,db:null,authApi:null,dbApi:null,appApi:null};
const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const id=()=>Math.random().toString(36).slice(2)+Date.now().toString(36), slug=s=>String(s||"").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9._-]/g,""), initials=n=>String(n||"HS").trim().split(/\s+/).slice(-2).map(x=>x[0]).join("").toUpperCase().slice(0,2)||"HS";
function mkWeek(dt){let d=new Date(dt);d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d.toISOString().slice(0,10)}
function weekLabel(k){const a=new Date(k+"T00:00:00"),b=new Date(a);b.setDate(b.getDate()+6);return `${a.toLocaleDateString("vi-VN",{day:"2-digit",month:"2-digit"})} – ${b.toLocaleDateString("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric"})}`}
const roleLabel=r=>({gvcn:"GVCN",lopTruong:"Lớp trưởng",lopPho:"Lớp phó",toTruong:"Tổ trưởng",toPho:"Tổ phó",student:"Học sinh"}[r]||"Người dùng");
const isGvcn=()=>state.profile?.role==="gvcn";
const isStaff=()=>["gvcn","lopTruong","lopPho","toTruong","toPho"].includes(state.profile?.role);
const isGroupRole=()=>["toTruong","toPho"].includes(state.profile?.role);
const crossOn=()=>state.config?.crossGrading==="assigned";
const crossTargetOf=g=>{if(!crossOn()||g==null||g==="")return null;const t=state.config?.crossTargets?.[String(g)];return t!=null&&String(t)!==""&&String(t)!==String(g)?String(t):null};
const myTarget=()=>isGroupRole()?crossTargetOf(state.profile?.group):null;
const sameGroup=s=>!!state.profile?.group&&String(s?.group)===String(state.profile.group);
const canGradeStudent=s=>{if(!s)return false;if(isGvcn()||["lopTruong","lopPho"].includes(state.profile?.role))return true;if(!isGroupRole())return false;const t=myTarget();return t?String(s.group)===t:sameGroup(s)};
const scopeStudent=s=>canGradeStudent(s)||(isGroupRole()&&sameGroup(s));
const locked=()=>!!state.weeks[state.week]?.finalized;
function saveLocal(){try{localStorage.setItem("td12a7-v5",JSON.stringify({config:state.config,groups:state.groups,students:state.students,users:state.users,records:state.records,reports:state.reports,weeks:state.weeks,audit:state.audit,week:state.week}))}catch{}}
function loadLocal(){try{const d=JSON.parse(localStorage.getItem("td12a7-v5")||"null");if(d)Object.assign(state,d)}catch{}}
function toast(msg,type=""){const e=document.createElement("div");e.className=`toast ${type}`;e.textContent=msg;$("#toastroot").appendChild(e);setTimeout(()=>e.remove(),3000)}
function grade(x){return x>=90?["Tốt","good"]:x>=80?["Khá","ok"]:x>=65?["Đạt","warn"]:["Cần cố gắng","bad"]}
function calc(studentId){const rs=Object.values(state.records).filter(r=>r.week===state.week&&r.studentId===studentId&&r.status!=="rejected"&&r.status!=="pending"&&r.status!=="deleted");const plus=rs.filter(r=>r.type==="plus").reduce((a,r)=>a+Number(r.points||0),0),minus=rs.filter(r=>r.type==="minus").reduce((a,r)=>a+Math.abs(Number(r.points||0)),0),pending=Object.values(state.records).filter(r=>r.week===state.week&&r.studentId===studentId&&r.status==="pending").length;return{plus,minus,pending,score:Math.min(100,100+plus-minus)}}
function rows(){return Object.values(state.students).filter(s=>s.active!==false).map(s=>({st:s,...calc(s.id)})).sort((a,b)=>b.score-a.score||b.plus-a.plus||String(a.st.id??"").localeCompare(String(b.st.id??""),"vi",{numeric:true})||a.st.name.localeCompare(b.st.name,"vi"))}
function visibleRows(){return rows().filter(r=>(state.group==="all"||String(r.st.group)===String(state.group))&&(!state.search||(`${r.st.id} ${r.st.name}`).toLowerCase().includes(state.search.toLowerCase())))}
function groupList(){return Object.values(state.groups).sort((a,b)=>Number(a.id)-Number(b.id))}
function compareStudentsByGroup(a,b){const groupNumber=value=>{const match=String(value??"").match(/\d+/);return match?Number(match[0]):Number.MAX_SAFE_INTEGER};return groupNumber(a.group)-groupNumber(b.group)||String(a.group??"").localeCompare(String(b.group??""),"vi",{numeric:true})||String(a.id??"").localeCompare(String(b.id??""),"vi",{numeric:true})||String(a.name??"").localeCompare(String(b.name??""),"vi")}
function accountEmail(username){return `${slug(username)}@auth.${slug(state.config?.classKey||state.config?.className||"thi-dua")}.app`}
function classKey(){return slug(state.config?.classKey||state.config?.className||state.setup?.classKey||"thi-dua")||"thi-dua"}
function localAccountEmail(username,classKeyValue){return `${slug(username)}@auth.${slug(classKeyValue||classKey())}.app`}
function currentActor(){return state.profile?`${roleLabel(state.profile.role)}${state.profile.group?` • Tổ ${state.profile.group}`:""}`:""}
function canWriteRecord(){return isStaff()&&!locked()}
function roleScopeText(){if(isGvcn())return "Toàn lớp";if(["lopTruong","lopPho"].includes(state.profile?.role))return "Toàn lớp";if(isGroupRole())return myTarget()?`Tổ ${state.profile.group} · chấm Tổ ${myTarget()}`:`Tổ ${state.profile.group}`;return "Chỉ xem"}

function firebaseErrMsg(fallback){const e=state.syncError;const code=String(e?.code||e?.message||e?.friendly||"");if(code.includes("PERMISSION_DENIED")||code.includes("permission-denied")||(e&&e.friendly))return e?.friendly||"Không đủ quyền Firebase (PERMISSION_DENIED). GVCN hãy publish lại Rules; cán bộ chỉ sửa bản ghi do mình tạo và tuần chưa chốt.";return fallback||"Không ghi được Firebase."}

async function dbSet(path,val){if(!fb.db)return false;try{await fb.dbApi.set(fb.dbApi.ref(fb.db,path),val);state.syncError=null;return true}catch(e){state.syncError=e;console.warn("Firebase write failed",path,e);const code=e?.code||e?.message||"";if(String(code).includes("PERMISSION_DENIED")||String(code).includes("permission-denied")){state.syncError={...e,friendly:"Firebase từ chối ghi (PERMISSION_DENIED). Kiểm tra Rules đã publish và tài khoản còn active / đúng vai trò."}}return false}}
async function dbGet(path){if(!fb.db)throw new Error("firebase-not-ready");return await fb.dbApi.get(fb.dbApi.ref(fb.db,path))}
async function dbGetWithTimeout(path,timeoutMs=10000){let timer;try{return await Promise.race([dbGet(path),new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error("firebase-timeout")),timeoutMs)})])}finally{clearTimeout(timer)}}
async function syncAll(){
  if(!fb.db)return false;
  try{
    const [cfg,groups,students,records,weeks]=await Promise.all([PATH.config,PATH.groups,PATH.students,PATH.records,PATH.weeks].map(dbGet));
    state.config=cfg.exists()?cfg.val():state.config;
    state.groups=groups.exists()?groups.val()||{}:{};
    state.students=students.exists()?students.val()||{}:{};
    state.records=records.exists()?records.val()||{}:{};
    state.weeks=weeks.exists()?weeks.val()||{}:{};
    if(isGvcn()){
      const [users,reports,audit]=await Promise.all([PATH.users,PATH.reports,PATH.audit].map(dbGet));
      const rawUsers=users.exists()?users.val()||{}:{};
      state.users=Object.fromEntries(Object.entries(rawUsers).map(([uid,user])=>[uid,{...user,uid}]));
      state.reports=reports.exists()?reports.val()||{}:{};
      state.audit=audit.exists()?audit.val()||{}:{};
    }else{state.users={};state.reports={};state.audit={}}
    state.syncError=null;saveLocal();return true;
  }catch(e){state.syncError=e;console.warn("Firebase sync failed",e);const code=String(e?.code||e?.message||"");if(code.includes("PERMISSION_DENIED")||code.includes("permission-denied")){console.warn("Gợi ý: Publish lại Firebase Rules. Node weeks/reports cần .read ở cấp cha để syncAll hoạt động.")}return false}
}

async function verifyStudents(expectedStudents){const snap=await dbGet(PATH.students);if(!snap?.exists())return{ok:false,count:0,missing:Object.keys(expectedStudents),extra:[]};const actual=snap.val()||{};const ids=Object.keys(expectedStudents);const missing=ids.filter(k=>!actual[k]);const count=ids.filter(k=>actual[k]?.active!==false).length;return{ok:missing.length===0&&count===ids.length,count,missing,actual};}
function shell(html){return `<div class="app">${topbar()}<main class="main">${html}</main><button class="fab no-print" data-action="anonymous-report">📣 Phản ánh ẩn danh</button></div>`}
function topbar(){const nav=[['home','Tổng quan'],['records','Nhật ký'],['students','Học sinh'],['rules','Quy chế']];if(isGvcn())nav.push(['reports','Phản ánh'],['manage','Quản lý']);return `<header class="top"><div class="topin"><div class="brand"><div class="logo">TD</div><div><div class="brand-title">Thi đua ${esc(state.config?.className||"")}</div><div class="brand-sub">${esc(state.config?.schoolYear||"")}</div></div></div><nav class="nav">${nav.map(n=>`<button class="${state.tab===n[0]?"active":""}" data-tab="${n[0]}">${n[1]}</button>`).join("")}</nav><div class="spacer"></div><div class="status"><i class="dot ${state.fbReady?"ok":""}"></i>${state.fbReady?"Đã đồng bộ":"Cục bộ"}</div><div class="userchip"><span class="avatar">${initials(state.profile?.name)}</span><span>${esc(state.profile?.name||"")} · ${esc(roleLabel(state.profile?.role))}</span></div>${isGvcn()?`<button class="btn small gray no-print" data-action="password">🔑</button>`:""}<button class="btn small dark no-print" data-action="logout">Thoát</button></div><div class="mnav">${nav.map(n=>`<button class="${state.tab===n[0]?"active":""}" data-tab="${n[0]}">${n[1]}</button>`).join("")}</div></header>`}
function dashboard(){const all=rows(),vis=visibleRows(),avg=all.length?all.reduce((a,r)=>a+r.score,0)/all.length:0,good=all.filter(r=>r.score>=90).length,pending=Object.values(state.records).filter(r=>r.week===state.week&&r.status==="pending"&&scopeStudent(state.students[r.studentId])).length;return `<section class="hero">${state.syncError?`<div class="warning no-print" style="margin-bottom:10px">${esc(state.syncError?.message||"Firebase đang gặp lỗi đồng bộ.")} <button class="btn small light" data-action="retry-sync">Thử lại</button></div>`:""}<div class="eyebrow"><span class="pill soft">${esc(currentActor())}</span><span class="pill ${locked()?"green":"amber"}">${locked()?"✓ Tuần đã chốt":"● Tuần đang mở"}</span><span class="pill soft">${roleScopeText()}</span></div><h1>${esc(state.config?.className||"")} · Tuần ${esc(weekLabel(state.week))}</h1><p>100 điểm cơ bản/tuần • điểm cộng tối đa +10 • điểm cuối tuần tối đa 100. GVCN là người kiểm tra và chốt điểm.</p><div class="actions no-print"><button class="btn light" data-action="week">📅 Đổi tuần</button>${canWriteRecord()?`<button class="btn green" data-action="plus">＋ Điểm cộng</button><button class="btn red" data-action="minus">− Điểm trừ</button>`:""}${isGvcn()?`<button class="btn amber" data-action="review">✓ Kiểm tra & chốt</button>`:""}</div></section><section class="stats"><div class="stat"><div class="stat-label">HS trong phạm vi</div><div class="stat-value">${vis.length}</div><div class="stat-sub">${isGvcn()?"Toàn lớp":"Theo vai trò"}</div></div><div class="stat"><div class="stat-label">Điểm trung bình</div><div class="stat-value">${avg.toFixed(1)}</div><div class="stat-sub">Tuần hiện tại</div></div><div class="stat"><div class="stat-label">Xếp loại Tốt</div><div class="stat-value">${good}</div><div class="stat-sub">Từ 90 điểm</div></div><div class="stat"><div class="stat-label">Chờ xem xét</div><div class="stat-value">${pending}</div><div class="stat-sub">Cần GVCN xử lý</div></div><div class="stat"><div class="stat-label">Trạng thái</div><div class="stat-value" style="font-size:19px">${locked()?"ĐÃ CHỐT":"ĐANG MỞ"}</div><div class="stat-sub">${locked()?"Không ghi thêm điểm":"Có thể ghi nhận"}</div></div></section><section class="grid"><div class="card"><div class="cardhead"><div><div class="title">Bảng xếp hạng</div><div class="sub">${esc(weekLabel(state.week))}</div></div><div class="actions" style="margin:0"><button class="btn small light no-print" data-action="csv">Xuất CSV</button><button class="btn small light no-print" data-action="print">In</button></div></div><div class="toolbar no-print"><div class="search"><input id="search" class="input" value="${esc(state.search)}" placeholder="🔎 Tìm mã hoặc tên học sinh"></div><select id="group" class="select" style="width:160px"><option value="all">Tất cả tổ</option>${groupList().map(g=>`<option value="${esc(g.id)}" ${String(state.group)===String(g.id)?"selected":""}>Tổ ${esc(g.name||g.id)}</option>`).join("")}</select></div><div class="tablewrap"><table class="table"><thead><tr><th>#</th><th>Học sinh</th><th>Tổ</th><th>Cộng</th><th>Trừ</th><th>Điểm</th><th>Xếp loại</th><th class="no-print"> </th></tr></thead><tbody>${vis.length?vis.map((r,i)=>{const [g,cls]=grade(r.score);return `<tr><td><strong>${i+1}</strong></td><td><div class="person"><div class="personava">${initials(r.st.name)}</div><div><div style="font-weight:900">${esc(r.st.name)}</div><div class="muted tiny">${esc(r.st.id)}</div></div></div></td><td>Tổ ${esc(r.st.group)}</td><td style="color:#047857;font-weight:900">+${r.plus}</td><td style="color:#be123c;font-weight:900">−${r.minus}</td><td><span class="score ${r.score>=90?"g":r.score>=65?"w":"b"}">${r.score}</span></td><td><span class="grade ${cls}">${g}</span>${r.pending?`<div class="tiny" style="margin-top:3px;color:#92400e">${r.pending} chờ</div>`:""}</td><td class="no-print"><button class="btn small gray" data-action="detail:${r.st.id}">Chi tiết</button></td></tr>`}).join(""):"<tr><td colspan='8' class='empty'>Chưa có học sinh.</td></tr>"}</tbody></table></div></div><div class="card"><div class="cardhead"><div><div class="title">Top tuần</div><div class="sub">Theo điểm hiện tại</div></div></div><div class="pad"><div class="list">${vis.slice(0,7).map((r,i)=>`<div class="item"><div class="itemrow"><div class="rank">${i+1}</div><div class="grow"><div class="fw">${esc(r.st.name)}</div><div class="tiny muted">Tổ ${esc(r.st.group)}</div></div><strong>${r.score}</strong></div></div>`).join("")||'<div class="empty">Chưa có dữ liệu.</div>'}</div><div class="sectionline"></div><div class="notice">Quy trình: tổ trưởng ghi nhận → trường hợp chưa rõ để “Chờ GVCN” → GVCN kiểm tra → chốt tuần.</div></div></div></section>`}
function recordsPage(){const rs=Object.values(state.records).filter(r=>r.week===state.week&&r.status!=="deleted"&&scopeStudent(state.students[r.studentId])).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));return `<h2 class="page-title">Nhật ký ghi nhận</h2><p class="page-sub">Các ghi nhận đang còn hiệu lực. Bản ghi đã xóa chỉ được lưu trong Audit.</p><div class="actions no-print"><button class="btn green" data-action="plus" ${canWriteRecord()?"":"disabled"}>＋ Điểm cộng</button><button class="btn red" data-action="minus" ${canWriteRecord()?"":"disabled"}>− Điểm trừ</button></div><div class="card" style="margin-top:12px"><div class="pad"><div class="recordlist">${rs.length?rs.map(recordCard).join(""):"<div class='empty'>Chưa có ghi nhận trong tuần này.</div>"}</div></div></div>`}
function canEditRecord(r){if(!state.user||!isStaff()||locked()||r?.status==="deleted")return false;if(isGvcn())return true;if(r.status==="rejected")return false;return r.createdByUid===state.user.uid&&canGradeStudent(state.students[r.studentId])}
function canDeleteRecord(r){return canEditRecord(r)}
function recordCard(r){const st=state.students[r.studentId],who=state.users[r.createdByUid]?.name||r.createdByName||"Cán bộ lớp",editable=canEditRecord(r),deletable=canDeleteRecord(r),statusLabel=r.status==="pending"?"Chờ GVCN":r.status==="rejected"?"Đã bỏ":r.status==="deleted"?"Đã xóa":"Đã duyệt";return `<div class="record ${r.status}"><div class="recrow"><div class="recicon ${r.type}">${r.type==="plus"?"＋":"−"}</div><div class="grow"><div class="fw">${esc(st?.name||r.studentId)} · Tổ ${esc(st?.group||r.studentGroup||"?")}</div><div class="recmeta">${esc(r.kind)} • ${esc(r.note||"Không có ghi chú")}<br>${esc(r.date||"")} • Người ghi: ${esc(who)} • <strong>${statusLabel}</strong>${r.updatedAt?` • Đã sửa ${new Date(r.updatedAt).toLocaleString("vi-VN")}`:""}${r.deletedAt?` • Xóa ${new Date(r.deletedAt).toLocaleString("vi-VN")}`:""}</div></div><div class="recright" style="color:${r.type==="plus"?"#047857":"#be123c"}">${r.type==="plus"?"+":"−"}${Math.abs(Number(r.points||0))}</div></div>${(editable||deletable)?`<div class="recactions no-print">${editable?`<button class="btn small light" data-action="edit-record:${r.id}">✎ Sửa</button>`:""}${deletable?`<button class="btn small light dangerline" data-action="delete-record:${r.id}">🗑 Xóa</button>`:""}</div>`:""}</div>`}
async function writeAudit(action,r,extra={}){const a={id:id(),action,recordId:r?.id||null,week:r?.week||state.week,studentId:r?.studentId||null,studentName:r?.studentId?(state.students[r.studentId]?.name||r.studentId):null,studentGroup:r?.studentGroup||state.students[r?.studentId]?.group||null,actorUid:state.user?.uid||null,actorName:state.profile?.name||"",at:Date.now(),...extra};state.audit[a.id]=a;saveLocal();if(fb.db&&!await dbSet(`${PATH.audit}/${a.id}`,a))toast("Dữ liệu đã thay đổi nhưng nhật ký chưa đồng bộ Firebase.","err");return a}
async function writeSystemAudit(action,targetType,targetId,before,after){return writeAudit(action,{id:targetId,week:state.week},{targetType,targetId,before,after})}
function toastAction(msg,label,fn){const e=document.createElement("div");e.className="toast ok actiontoast";const t=document.createElement("span");t.textContent=msg;const b=document.createElement("button");b.className="toastundo";b.textContent=label;b.onclick=async()=>{b.disabled=true;await fn();e.remove()};e.append(t,b);$("#toastroot").appendChild(e);setTimeout(()=>e.remove(),12000)}
async function editRecord(rid){const r=state.records[rid];if(!r||!canEditRecord(r))return toast("Bạn không có quyền sửa bản ghi này hoặc tuần đã chốt.","err");recordModal(r.type,{record:r})}
async function deleteRecord(rid){const r=state.records[rid];if(!r||!canDeleteRecord(r))return toast("Bạn không có quyền xóa bản ghi này hoặc tuần đã chốt.","err");const currentStudent=state.students[r.studentId];if(!confirm(`Xóa ghi nhận của ${currentStudent?.name||r.studentId}: ${r.kind} (${r.points>0?"+":"−"}${Math.abs(r.points)})?`))return;const snapshot=JSON.parse(JSON.stringify(r));const deleted={...r,status:"deleted",deletedAt:Date.now(),deletedByUid:state.user.uid,deletedByName:state.profile?.name||"",previousData:snapshot,updatedAt:Date.now()};if(!(await dbSet(`records/${rid}`,deleted)))return toast(firebaseErrMsg("Không xóa được Firebase."),"err");state.records[rid]=deleted;state.lastDeleted={record:snapshot,expiresAt:Date.now()+12000};await writeAudit("DELETE",deleted,{before:snapshot,after:deleted});renderApp();toastAction("Đã xóa ghi nhận.","Hoàn tác",async()=>{if(!state.lastDeleted||state.lastDeleted.expiresAt<Date.now())return toast("Đã hết thời gian hoàn tác.","err");const restored={...state.lastDeleted.record,status:state.lastDeleted.record.status==="deleted"?"approved":state.lastDeleted.record.status,deletedAt:null,deletedByUid:null,deletedByName:null,previousData:null,updatedAt:Date.now()};if(!(await dbSet(`records/${restored.id}`,restored)))return toast("Không thể hoàn tác trên Firebase.","err");state.records[restored.id]=restored;await writeAudit("RESTORE",restored,{before:deleted,after:restored,restored:true});state.lastDeleted=null;renderApp();toast("Đã hoàn tác bản ghi.","ok")})}
function studentsPage(){const list=Object.values(state.students).sort(compareStudentsByGroup);return `<h2 class="page-title">Học sinh</h2><p class="page-sub">Danh sách lớp dùng đúng thứ tự: <strong>Mã học sinh · Họ và tên · Tổ</strong>; bảng được sắp theo tổ, rồi theo mã học sinh.</p>${isGvcn()?`<div class="actions no-print"><button class="btn blue" data-action="edit-roster">✎ Sửa danh sách</button><button class="btn light" data-action="csv-students">Xuất danh sách</button></div>`:""}<div class="card" style="margin-top:12px"><div class="tablewrap"><table class="table"><thead><tr><th>Mã học sinh</th><th>Họ và tên</th><th>Tổ</th><th>Trạng thái</th></tr></thead><tbody>${list.length?list.map(s=>`<tr><td>${esc(s.id)}</td><td style="font-weight:900">${esc(s.name)}</td><td>Tổ ${esc(s.group)}</td><td><span class="statusbadge ${s.active===false?"off":"on"}">${s.active===false?"Đã ẩn":"Đang học"}</span></td></tr>`).join(""):"<tr><td colspan='4' class='empty'>Chưa có học sinh.</td></tr>"}</tbody></table></div></div>`}
function rulesPage(){return `<h2 class="page-title">Quy chế thi đua</h2><p class="page-sub">Hiển thị trực tiếp thang điểm của lớp ${esc(state.config?.className||"")}.</p><div class="grid"><div class="card"><div class="cardhead"><div class="title">Điểm trừ</div></div><div class="pad">${RULES_MINUS.map(x=>`<div class="item" style="margin-bottom:7px"><div class="itemrow"><div class="grow">${esc(x[0])}</div><strong style="color:#be123c">${x[1]===null?"−5 đến −10":x[1]}</strong></div></div>`).join("")}</div></div><div class="card"><div class="cardhead"><div class="title">Điểm cộng</div></div><div class="pad">${RULES_PLUS.map(x=>`<div class="item" style="margin-bottom:7px"><div class="itemrow"><div class="grow">${esc(x[0])}</div><strong style="color:#047857">+${x[1]}</strong></div></div>`).join("")}<div class="sectionline"></div><div class="success">Điểm cộng tối đa: +10 điểm/tuần.</div><div class="notice" style="margin-top:8px">Điểm cuối tuần = 100 + điểm cộng − điểm trừ; tối đa 100 điểm.</div><div class="warning" style="margin-top:8px">Học sinh ốm/điều trị/nằm viện có phép và căn cứ phù hợp thì không trừ. Được GV cho phép dùng điện thoại phục vụ học tập thì không tính vi phạm.</div></div></div></div>`}
function reportsPage(){const rs=Object.values(state.reports).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));return `<h2 class="page-title">Phản ánh ẩn danh</h2><p class="page-sub">Chỉ GVCN xem được hộp thư này. Người gửi không cần tài khoản.</p><div class="card"><div class="pad"><div class="recordlist">${rs.length?rs.map(r=>`<div class="record ${r.status==='new'?"pending":""}"><div class="recrow"><div class="recicon" style="background:#ede9fe;color:#6d28d9">📣</div><div class="grow"><div class="fw">${esc(r.category||"Phản ánh")}</div><div class="recmeta">${r.target?`Đối tượng: ${esc(r.target)}<br>`:""}${esc(r.content)}<br>${new Date(Number(r.createdAt||Date.now())).toLocaleString("vi-VN")} • ${r.status==='new'?"Mới":"Đã xử lý"}</div></div></div>${r.status==='new'?`<div class="recactions no-print"><button class="btn small green" data-action="handle-report:${r.id}">✓ Đã xử lý</button><button class="btn small light" data-action="report-record:${r.id}">Tạo ghi nhận</button></div>`:""}</div>`).join(""):"<div class='empty'>Chưa có phản ánh.</div>"}</div></div></div>`}
function accountForm(uid){const existing=uid?state.users[uid]:null;if(uid&&!existing)return;const roles=["gvcn","lopTruong","lopPho","toTruong","toPho","student"];const roleOptions=roles.map(r=>`<option value="${esc(r)}" ${existing?.role===r?"selected":""}>${esc(roleLabel(r))}</option>`).join("");const groupOptions=`<option value="">-- Không --</option>${groupList().map(g=>`<option value="${esc(g.id)}" ${String(existing?.group||"")===String(g.id)?"selected":""}>Tổ ${esc(g.name||g.id)}</option>`).join("")}`;const pass=existing?"":`<label class="field fullcol"><span class="label">Mật khẩu ban đầu</span><input id="ac-pass" class="input" type="password" minlength="6" required></label>`;openModal(existing?"Sửa tài khoản":"Tạo tài khoản",`<form id="account-form"><div class="formgrid"><label class="field"><span class="label">Tên đăng nhập</span><input id="ac-user" class="input" value="${esc(existing?.username||"")}" ${existing?"readonly":""} required></label><label class="field"><span class="label">Họ tên</span><input id="ac-name" class="input" value="${esc(existing?.name||"")}" required></label><label class="field"><span class="label">Vai trò</span><select id="ac-role" class="select">${roleOptions}</select></label><label class="field"><span class="label">Tổ</span><select id="ac-group" class="select">${groupOptions}</select></label>${pass}</div><div class="warning" style="margin-top:10px">Không nhập email. Hệ thống vẫn dùng tên đăng nhập ở giao diện.</div><div class="actions" style="justify-content:flex-end"><button class="btn light" type="button" data-action="close">Hủy</button><button class="btn dark" type="submit">${existing?"Lưu thay đổi":"Tạo tài khoản"}</button></div></form>`);$('#account-form').onsubmit=async e=>{e.preventDefault();const username=$('#ac-user').value.trim().toUpperCase().replace(/\s+/g,"");const name=$('#ac-name').value.trim(),role=$('#ac-role').value,group=$('#ac-group').value||null;if(!username||!name)return toast("Thiếu tên đăng nhập hoặc họ tên.","err");if(["toTruong","toPho"].includes(role)&&!group)return toast("Tổ trưởng/tổ phó phải có tổ.","err");if(existing){const before={...existing},next={...existing,name,role,group};if(!(await dbSet(`users/${uid}`,next)))return toast(firebaseErrMsg("Không cập nhật được tài khoản."),"err");const verify=await dbGet(`users/${uid}`);if(!verify.exists())return toast("Không xác minh được sau khi lưu.","err");state.users[uid]=verify.val();await writeSystemAudit("UPDATE","user",uid,before,state.users[uid]);closeModal();renderApp();toast("Đã cập nhật tài khoản.","ok");return}if(Object.values(state.users).some(u=>String(u.username||"").toUpperCase()===username))return toast("Tên đăng nhập đã tồn tại.","err");const password=$('#ac-pass').value;if(password.length<6)return toast("Mật khẩu tối thiểu 6 ký tự.","err");try{const made=await createAuthUser(username,password);const profile={username,name,role,group,active:true,createdAt:Date.now()};if(!(await dbSet(`users/${made.uid}`,profile)))throw new Error("profile-write-failed");try{await fb.appApi.deleteApp(made.app)}catch{}state.users[made.uid]={...profile,uid:made.uid};await writeSystemAudit("CREATE","user",made.uid,null,state.users[made.uid]);closeModal();renderApp();toast("Đã tạo tài khoản.","ok")}catch(e){console.error(e);toast(e?.code==="auth/email-already-in-use"?"Tên đăng nhập đã tồn tại.":"Tạo tài khoản thất bại.","err")}}}
function managePage(){
  if(!isGvcn())return dashboard();
  const activeStudents=Object.values(state.students).filter(s=>s.active!==false);
  const gs=groupList();
  const us=Object.values(state.users).sort((a,b)=>roleLabel(a.role).localeCompare(roleLabel(b.role),'vi')||String(a.name||'').localeCompare(String(b.name||''),'vi'));
  const staff=us.filter(u=>u.role!=="student");
  const currentRows=rows();
  const avg=currentRows.length?currentRows.reduce((a,r)=>a+r.score,0)/currentRows.length:0;
  const pendingRecords=Object.values(state.records).filter(r=>r.week===state.week&&r.status==='pending');
  const newReports=Object.values(state.reports).filter(r=>r.status==='new');
  const todoCount=pendingRecords.length+newReports.length;
  const recent=Object.values(state.records).filter(r=>r.week===state.week&&r.status!=="deleted").sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0)).slice(0,8);
  const audits=Object.values(state.audit).sort((a,b)=>Number(b.at||0)-Number(a.at||0)).slice(0,18);
  const gvcnName=state.profile?.name||'GVCN';
  const roleAccounts=[['GVCN','gvcn'],['Lớp trưởng','lopTruong'],['Lớp phó','lopPho'],['Tổ trưởng','toTruong'],['Tổ phó','toPho'],['HOCSINH','student']];
  const auditLabel=a=>a.action==='delete'?'🗑 Xóa':a.action==='undo-delete'?'↶ Hoàn tác':a.action==='edit'?'✎ Sửa':a.action==='approve'?'✓ Duyệt':a.action==='reject'?'⊘ Bỏ':'• Cập nhật';
  const auditDetail=a=>{
    const from=a.fromStudentName&&a.toStudentName&&a.fromStudentName!==a.toStudentName?`Đổi: ${esc(a.fromStudentName)} → ${esc(a.toStudentName)}`:`HS: ${esc(a.studentName||a.studentId||'')}`;
    return `${from}${a.at?` • ${new Date(Number(a.at)).toLocaleString('vi-VN')}`:''}`;
  };
  return `<div class="hero"><div class="eyebrow"><span class="pill soft">${esc(gvcnName)} · GVCN</span><span class="pill ${locked()?'green':'amber'}">${locked()?'✓ Tuần đã chốt':'● Tuần đang mở'}</span><span class="pill soft">Trung tâm điều khiển lớp</span></div><h1>Dashboard GVCN</h1><p>${esc(state.config?.className||'')} · ${esc(state.config?.schoolYear||'')} · Tuần ${esc(weekLabel(state.week))}</p><div class="actions no-print"><button class="btn light" data-action="week">📅 Đổi tuần</button><button class="btn dark" data-action="backup-json">⇩ Sao lưu JSON</button><button class="btn light" data-action="import-backup">⇧ Khôi phục JSON</button><button class="btn amber" data-action="review">✓ Kiểm tra & chốt</button></div></div>

  <section class="stats">
    <div class="stat"><div class="stat-label">Sĩ số</div><div class="stat-value">${activeStudents.length}</div><div class="stat-sub">Học sinh đang học</div></div>
    <div class="stat"><div class="stat-label">Số tổ</div><div class="stat-value">${gs.length}</div><div class="stat-sub">Cấu trúc lớp</div></div>
    <div class="stat"><div class="stat-label">Số cán bộ</div><div class="stat-value">${staff.length}</div><div class="stat-sub">Tài khoản riêng</div></div>
    <div class="stat"><div class="stat-label">Điểm TB tuần</div><div class="stat-value">${avg.toFixed(1)}</div><div class="stat-sub">${esc(weekLabel(state.week))}</div></div>
    <div class="stat"><div class="stat-label">Việc chờ xử lý</div><div class="stat-value">${todoCount}</div><div class="stat-sub">${pendingRecords.length} bản ghi + ${newReports.length} phản ánh</div></div>
  </section>

  ${crossGradingCard()}
  <div class="grid">
    <div class="card"><div class="cardhead"><div><div class="title">Cấu trúc lớp</div><div class="sub">Từng tổ · sĩ số · tổ trưởng · tổ phó</div></div><button class="btn small blue no-print" data-action="edit-structure">✎ Chỉnh cấu trúc</button><button class="btn small violet no-print" data-action="assign-officers">👥 Đổi chức vụ</button></div><div class="pad"><div class="list">${gs.map(g=>{const members=activeStudents.filter(s=>String(s.group)===String(g.id));return `<div class="accountcard"><div class="rank">${esc(g.id)}</div><div class="grow"><div class="fw">Tổ ${esc(g.name||g.id)} · ${members.length} HS</div><div class="tiny muted">Tổ trưởng: ${esc(g.leaderName||'Chưa phân công')} ${g.deputyName?`• Tổ phó: ${esc(g.deputyName)}`:'• Chưa có tổ phó'}</div></div><span class="statusbadge on">${members.length} HS</span></div>`}).join('')||'<div class="empty">Chưa có tổ.</div>'}</div></div></div>

    <div class="card"><div class="cardhead"><div><div class="title">Cảnh báo</div><div class="sub">Những việc cần GVCN chú ý</div></div></div><div class="pad"><div class="list"><div class="item"><div class="itemrow"><span class="grade ${pendingRecords.length?'warn':'good'}">${pendingRecords.length?'CẦN XỬ LÝ':'ỔN'}</span><div class="grow"><div class="fw">Bản ghi chờ GVCN</div><div class="tiny muted">${pendingRecords.length} bản ghi trong tuần</div></div>${pendingRecords.length?`<button class="btn small amber" data-action="review">Xem</button>`:''}</div></div><div class="item"><div class="itemrow"><span class="grade ${newReports.length?'warn':'good'}">${newReports.length?'MỚI':'ỔN'}</span><div class="grow"><div class="fw">Phản ánh mới</div><div class="tiny muted">${newReports.length} phản ánh chưa xử lý</div></div>${newReports.length?`<button class="btn small light" data-tab="reports">Mở hộp thư</button>`:''}</div></div><div class="item"><div class="itemrow"><span class="grade ${locked()?'good':'ok'}">${locked()?'ĐÃ CHỐT':'ĐANG MỞ'}</span><div class="grow"><div class="fw">Trạng thái tuần</div><div class="tiny muted">${esc(weekLabel(state.week))}</div></div>${locked()?`<button class="btn small light" data-action="unfinalize">Mở lại</button>`:''}</div></div></div></div></div>
  </div>

  <div class="card" style="margin-top:14px"><div class="cardhead"><div><div class="title">Tài khoản</div><div class="sub">GVCN · Lớp trưởng · Lớp phó · Tổ trưởng · Tổ phó · HOCSINH</div></div></div><div class="pad"><div class="three">${roleAccounts.map(([label,role])=>{const count=us.filter(u=>u.role===role).length;return `<div class="accountcard"><div class="grow"><div class="fw">${esc(label)}</div><div class="tiny muted">${count} tài khoản</div></div><span class="accountbadge">${count}</span></div>`}).join('')}</div><div class="list" style="margin-top:10px">${us.map(u=>`<div class="accountcard"><div class="avatar">${initials(u.name)}</div><div class="grow"><div class="fw">${esc(u.name)}</div><div class="tiny muted">${esc(roleLabel(u.role))}${u.group?` • Tổ ${esc(u.group)}`:''}</div></div><span class="accountbadge">${esc(u.username)}</span><span class="statusbadge ${u.active===false?'off':'on'}">${u.active===false?'Khóa':'Đang dùng'}</span>${u.username!=='GVCN'?`<button class="btn small light no-print" data-action="edit-account:${u.uid}">✎ Sửa</button><button class="btn small ${u.active===false?'green':'light'} no-print" data-action="toggle-user:${u.uid}">${u.active===false?'Mở':'Khóa'}</button>`:''}</div>`).join('')||'<div class="empty">Chưa có tài khoản.</div>'}</div></div></div>

  <div class="grid" style="margin-top:14px"><div class="card"><div class="cardhead"><div><div class="title">Hoạt động gần đây</div><div class="sub">Bản ghi vừa cộng/trừ · người ghi · học sinh · mức điểm</div></div><button class="btn small light no-print" data-action="records">Xem toàn bộ</button></div><div class="pad"><div class="recordlist">${recent.length?recent.map(recordCard).join(''):'<div class="empty">Chưa có bản ghi trong tuần.</div>'}</div></div></div>
    <div class="card"><div class="cardhead"><div><div class="title">Lịch sử chỉnh sửa</div><div class="sub">Sửa · xóa · hoàn tác và thời gian thực hiện</div></div></div><div class="pad"><div class="recordlist">${audits.map(a=>`<div class="accountcard"><div class="recicon ${a.action==='delete'?'minus':a.action==='undo-delete'?'plus':''}">${a.action==='delete'?'🗑':a.action==='undo-delete'?'↶':'✎'}</div><div class="grow"><div class="fw">${esc(auditLabel(a))} · ${esc(a.actorName||'Cán bộ')}</div><div class="tiny muted">${auditDetail(a)}${a.recordId?` • Mã: ${esc(a.recordId)}`:''}</div>${a.before&&a.after&&a.action==='edit'?`<div class="tiny muted" style="margin-top:3px">Trước: ${esc(a.before.kind||'')} ${Number(a.before.points)>0?'+':'−'}${Math.abs(Number(a.before.points||0))} → Sau: ${esc(a.after.kind||'')} ${Number(a.after.points)>0?'+':'−'}${Math.abs(Number(a.after.points||0))}</div>`:''}</div></div>`).join('')||'<div class="empty">Chưa có lịch sử chỉnh sửa.</div>'}</div></div></div>
  </div>

  <div class="card" style="margin-top:14px"><div class="cardhead"><div><div class="title">Sao lưu dữ liệu</div><div class="sub">Xuất toàn bộ dữ liệu lớp thành JSON để lưu dự phòng</div></div><div class="actions" style="margin:0"><button class="btn small dark no-print" data-action="backup-json">⇩ Xuất JSON</button><button class="btn small light no-print" data-action="import-backup">⇧ Nhập JSON</button></div></div><div class="pad"><div class="notice">Bản sao lưu gồm cấu hình lớp, tổ, học sinh, tài khoản, bản ghi, phản ánh, tuần và lịch sử chỉnh sửa. Không chứa mật khẩu Firebase Authentication.</div></div></div>`;
}
function settingsPage(){return `<h2 class="page-title">Thiết lập</h2><p class="page-sub">Thông tin cơ bản và thao tác hệ thống.</p><div class="two"><div class="card"><div class="cardhead"><div class="title">Thông tin lớp</div></div><div class="pad"><div class="formgrid"><label class="field"><span class="label">Tên lớp</span><input id="cfg-class" class="input" value="${esc(state.config?.className||"")}"></label><label class="field"><span class="label">Năm học</span><input id="cfg-year" class="input" value="${esc(state.config?.schoolYear||"")}"></label></div><div class="actions"><button class="btn dark" data-action="save-config">Lưu</button></div></div></div><div class="card"><div class="cardhead"><div class="title">Tài khoản học sinh chung</div></div><div class="pad"><div class="notice">Tên đăng nhập: <strong>HOCSINH</strong>. Học sinh dùng chung một tài khoản và chỉ có quyền xem dữ liệu.</div><div class="actions"><button class="btn light" data-action="password">Đổi mật khẩu tài khoản đang đăng nhập</button></div></div></div></div>`}
function crossGradingCard(){const gs=groupList(),on=crossOn(),T=state.config?.crossTargets||{};const rowsH=gs.map(g=>{const cur=crossTargetOf(g.id);return `<div class="two" style="align-items:center;margin-bottom:8px"><div class="fw">Tổ ${esc(g.name||g.id)} chấm</div><select class="select cross-target" data-g="${esc(g.id)}"><option value="">Tổ mình (không đổi)</option>${gs.filter(x=>String(x.id)!==String(g.id)).map(x=>`<option value="${esc(x.id)}" ${cur===String(x.id)?"selected":""}>Tổ ${esc(x.name||x.id)}</option>`).join("")}</select></div>`}).join("");return `<div class="card" style="margin-bottom:14px"><div class="cardhead"><div><div class="title">Chấm chéo giữa các tổ</div><div class="sub">GVCN chỉ định mỗi tổ chấm 1 tổ khác</div></div></div><div class="pad"><div class="formgrid"><label class="field fullcol"><span class="label">Trạng thái</span><select id="cfg-cross" class="select"><option value="off" ${on?"":"selected"}>Tắt – mỗi tổ chấm tổ mình</option><option value="assigned" ${on?"selected":""}>Bật – mỗi tổ chấm tổ được chỉ định</option></select></label></div><div style="margin-top:12px">${rowsH}</div><div class="notice" style="margin-top:8px">Khi bật, tổ trưởng/tổ phó của tổ nào <strong>chỉ chấm được học sinh của tổ được chỉ định</strong> (không chấm tổ mình). Tổ để “Tổ mình” vẫn chấm tổ mình như cũ. Áp dụng ngay, bản ghi cũ không đổi. Lớp trưởng, lớp phó, GVCN vẫn chấm toàn lớp.</div><div class="actions"><button class="btn light" data-action="cross-rotate">↻ Gợi ý xoay vòng</button><button class="btn dark" data-action="save-cross">Lưu phân công chấm</button></div></div></div>`}
function crossRotate(){const sels=$$('.cross-target');const ids=sels.map(x=>x.dataset.g);sels.forEach((sel,i)=>{sel.value=ids.length>1?ids[(i+1)%ids.length]:""});const on=$('#cfg-cross');if(on)on.value="assigned"}
async function saveCrossGrading(){if(!isGvcn())return;const v=$('#cfg-cross')?.value==="assigned"?"assigned":"off";const targets={};$$('.cross-target').forEach(sel=>{const g=String(sel.dataset.g),t=String(sel.value||"");if(t&&t!==g&&state.groups[t])targets[g]=t});if(v==="assigned"&&!Object.keys(targets).length)return toast("Hãy chỉ định ít nhất một tổ chấm tổ khác, hoặc chọn Tắt.","err");const before=state.config;const cfg={...state.config,crossGrading:v};if(Object.keys(targets).length)cfg.crossTargets=targets;else delete cfg.crossTargets;if(!(await dbSet(PATH.config,cfg)))return toast("Không lưu được Firebase.","err");const verify=await dbGet(PATH.config);if(!verify.exists()||(verify.val().crossGrading||"off")!==v)return toast("Không xác minh được phân công sau khi lưu.","err");state.config=verify.val();saveLocal();await writeSystemAudit("UPDATE","classConfig",PATH.config,before,state.config);renderApp();const gs=groupList(),graded={};Object.values(targets).forEach(t=>graded[t]=(graded[t]||0)+1);const miss=gs.filter(g=>!graded[g.id]).map(g=>g.name||g.id),dup=gs.filter(g=>graded[g.id]>1).map(g=>g.name||g.id);toast(v==="off"?"Đã tắt chấm chéo.":"Đã lưu phân công chấm."+(miss.length?` Chưa có tổ nào chấm Tổ ${miss.join(", ")}.`:"")+(dup.length?` Tổ ${dup.join(", ")} bị nhiều tổ cùng chấm.`:""),"ok")}
async function saveConfig(){if(!isGvcn())return;const cfg={...state.config,className:$('#cfg-class').value.trim()||state.config.className,schoolYear:$('#cfg-year').value.trim()||state.config.schoolYear};const before=state.config;if(!(await dbSet(PATH.config,cfg)))return toast("Không lưu được Firebase.","err");const verify=await dbGet(PATH.config);if(!verify.exists())return toast("Không xác minh được cấu hình sau khi lưu.","err");state.config=verify.val();saveLocal();await writeSystemAudit("UPDATE","classConfig",PATH.config,before,state.config);renderApp();toast("Đã lưu.","ok")}
function validateBackupShape(b){
  if(!b||typeof b!=="object")return{ok:false,reason:"Tệp JSON không phải object."};
  const required=["classConfig","groups","students","users","records","audit"];
  const missing=required.filter(k=>!Object.prototype.hasOwnProperty.call(b,k));
  if(missing.length)return{ok:false,reason:`Thiếu trường: ${missing.join(", ")}.`};
  for(const k of required){if(b[k]===null||typeof b[k]!=="object")return{ok:false,reason:`Trường ${k} không hợp lệ.`}}
  return{ok:true};
}
function importBackupJson(){
  if(!isGvcn())return;
  const input=document.createElement("input"); input.type="file"; input.accept="application/json,.json"; input.style.display="none";
  document.body.appendChild(input);
  input.onchange=async()=>{
    const file=input.files?.[0]; input.remove(); if(!file)return;
    try{
      const parsed=JSON.parse(await file.text()),valid=validateBackupShape(parsed); if(!valid.ok)throw new Error(valid.reason); if(parsed.classConfig?.classKey&&state.config?.classKey&&String(parsed.classConfig.classKey)!==String(state.config.classKey))throw new Error(`Tệp sao lưu thuộc lớp khác (${parsed.classConfig.className||parsed.classConfig.classKey}).`);
      const activeStudents=Object.values(parsed.students||{}).filter(s=>s&&s.active!==false);
      const counts={students:Object.keys(parsed.students||{}).length,activeStudents:activeStudents.length,groups:Object.keys(parsed.groups||{}).length,users:Object.keys(parsed.users||{}).length,records:Object.keys(parsed.records||{}).length,audit:Object.keys(parsed.audit||{}).length,reports:Object.keys(parsed.reports||{}).length,weeks:Object.keys(parsed.weeks||{}).length};
      openModal("Xác nhận khôi phục JSON",`<div class="warning"><strong>Cảnh báo:</strong> thao tác này sẽ ghi đè dữ liệu lớp hiện tại bằng dữ liệu trong tệp. Không thể hoàn tác tự động nếu tệp sai.</div><div class="sectionline"></div><div class="three"><div class="stat"><div class="stat-label">Học sinh</div><div class="stat-value">${counts.students}</div><div class="stat-sub">${counts.activeStudents} đang học</div></div><div class="stat"><div class="stat-label">Tổ</div><div class="stat-value">${counts.groups}</div><div class="stat-sub">cấu trúc lớp</div></div><div class="stat"><div class="stat-label">Tài khoản</div><div class="stat-value">${counts.users}</div><div class="stat-sub">hồ sơ</div></div></div><div class="notice" style="margin-top:10px">Bản sao lưu không khôi phục mật khẩu Firebase Authentication. Hồ sơ tài khoản được khôi phục, còn mật khẩu vẫn giữ theo Firebase.</div><div class="actions" style="justify-content:flex-end"><button class="btn light" data-action="close">Hủy</button><button class="btn red" id="confirm-import-backup">Khôi phục dữ liệu</button></div>`);
      $('#confirm-import-backup').onclick=async()=>{
        const btn=$('#confirm-import-backup'); if(btn){btn.disabled=true;btn.textContent='Đang khôi phục...'}
        const currentUid=state.user?.uid,currentProfile=state.profile?{...state.profile}:null;
        try{
          const payloads=[['classConfig',parsed.classConfig],['groups',parsed.groups],['students',parsed.students],['records',parsed.records],['weeks',parsed.weeks||{}],['reports',parsed.reports||{}]];
          for(const [key,value] of payloads){if(!(await dbSet(PATH[key]||key,value)))throw new Error(`Không ghi được ${key}.`)}
          const importedUsers={...parsed.users};
          if(currentUid&&currentProfile)importedUsers[currentUid]=currentProfile;
          if(!(await dbSet(PATH.users,importedUsers)))throw new Error('Không ghi được users.');
          const v=await verifyStudents(activeStudents.reduce((o,x)=>(o[x.id]=x,o),{}));
          if(!v.ok)throw new Error(`Xác minh học sinh thất bại: ${v.count}/${activeStudents.length}.`);
          if(!(await dbSet(PATH.audit,parsed.audit||{})))throw new Error('Không ghi được audit.');
          await writeSystemAudit('IMPORT','backup',file.name,null,{counts,restoredAt:Date.now()});
          await syncAll(); closeModal(); renderApp(); toast(`Khôi phục thành công: ${counts.activeStudents} học sinh, ${counts.groups} tổ, ${counts.users} tài khoản.`, 'ok');
        }catch(err){console.error(err);if(btn){btn.disabled=false;btn.textContent='Khôi phục dữ liệu'}toast(`Khôi phục chưa hoàn tất: ${err?.message||'lỗi không xác định'}`,'err')}
      };
    }catch(err){toast(`Tệp sao lưu không hợp lệ: ${err?.message||'JSON lỗi'}`,'err')}
  };
  input.click();
}
async function exportBackupJson(){
  if(!isGvcn())return toast("Chỉ GVCN được xuất bản sao lưu.","err");
  const payload={
    schemaVersion:2,
    exportedAt:Date.now(),
    exportedBy:{uid:state.user?.uid||null,name:state.profile?.name||"GVCN"},
    classConfig:state.config||null,
    groups:state.groups||{},
    students:state.students||{},
    users:state.users||{},
    records:state.records||{},
    reports:state.reports||{},
    weeks:state.weeks||{},
    audit:state.audit||{}
  };
  const name=slug(state.config?.className||"lop")||"lop";
  download(JSON.stringify(payload,null,2),`sao-luu-${name}-${new Date().toISOString().slice(0,10)}.json`,`application/json;charset=utf-8`);
  await writeSystemAudit("EXPORT","backup","json",null,{file:name});toast("Đã xuất toàn bộ dữ liệu lớp thành JSON.","ok");
}

function csvFromRows(data){return "\ufeff"+data.map(r=>r.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\n")}
function download(text,name,type){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),400)}
function exportCsv(){const d=[["STT","Mã HS","Họ tên","Tổ","Cộng","Trừ","Điểm","Xếp loại"],...visibleRows().map((r,i)=>[i+1,r.st.id,r.st.name,r.st.group,r.plus,r.minus,r.score,grade(r.score)[0]])];download(csvFromRows(d),`thi-dua-${state.config.className}-${state.week}.csv`,`text/csv;charset=utf-8`)}
function exportStudents(){const d=[["Mã học sinh","Họ và tên","Tổ"],...Object.values(state.students).sort(compareStudentsByGroup).map(s=>[s.id,s.name,s.group])];download(csvFromRows(d),`danh-sach-${state.config.className}.csv`,`text/csv;charset=utf-8`)}
async function action(a){if(a==="anonymous-report")return anonymousReport();if(a==="retry-sync")return syncAll().then(ok=>{if(!ok)return toast("Chưa thể đồng bộ Firebase.","err");renderApp();toast("Đã đồng bộ lại.","ok")});if(a==="logout"){try{await fb.authApi.signOut(fb.auth)}catch{}state.user=null;state.profile=null;return loginView()}if(a==="password")return passwordModal();if(a==="plus")return recordModal("plus");if(a==="minus")return recordModal("minus");if(a==="week")return changeWeek();if(a==="records") {state.tab="records";return renderApp();}if(a==="review")return reviewWeek();if(a==="finalize")return finalizeWeek();if(a==="unfinalize")return unfinalize();if(a==="backup-json")return exportBackupJson();if(a==="import-backup")return importBackupJson();if(a==="csv")return exportCsv();if(a==="csv-students")return exportStudents();if(a==="print")return window.print();if(a==="detail")return; if(a.startsWith("detail:"))return detail(a.slice(7));if(a.startsWith("edit-record:"))return editRecord(a.slice(12));if(a.startsWith("delete-record:"))return deleteRecord(a.slice(14));if(a.startsWith("approve:"))return reviewRecord(a.slice(8),"approved");if(a.startsWith("reject:"))return reviewRecord(a.slice(7),"rejected");if(a.startsWith("handle-report:"))return handleReport(a.slice(14));if(a.startsWith("toggle-user:"))return toggleUser(a.slice(12));if(a.startsWith("edit-account:"))return accountForm(a.slice(13));if(a==="create-account")return accountForm();if(a.startsWith("report-record:"))return reportToRecord(a.slice(14));if(a==="edit-roster")return editRoster();if(a==="save-roster")return saveRoster();if(a==="edit-structure")return editStructure();if(a==="assign-officers")return assignOfficers();if(a==="save-config")return saveConfig();if(a==="save-cross")return saveCrossGrading();if(a==="cross-rotate")return crossRotate();if(a==="sample-roster"){state.setup.studentsText=sampleRoster();return setupView()}if(a==="setup-prev"){state.setupStep--;return setupView()}if(a==="setup-next")return setupNext();if(a==="close")return closeModal();if(a.startsWith("toggle-password:")){const idv=a.slice(16),el=document.getElementById(idv);if(!el)return;el.type=el.type==="password"?"text":"password";const btn=el.parentElement?.querySelector(".passbtn");if(btn)btn.textContent=el.type==="password"?"👁":"🙈";return}}
function sampleRoster(){return Array.from({length:30},(_,i)=>`A${String(i+1).padStart(2,"0")}\tHọc sinh ${i+1}\t${(i%4)+1}`).join("\n")}
function collectSetupStep(){const s=state.setup,step=state.setupStep;if(step===1){s.className=$('#s-class').value.trim();s.schoolYear=$('#s-year').value.trim()||"2026–2027";s.gvcnName=$('#s-gname').value.trim()||"GVCN";s.groupCount=Math.max(1,Math.min(15,Number($('#s-count').value)||4));s.gvcnPass=$('#s-gpass').value; if(s.gvcnPass.length<6)return false;s.groups=Array.from({length:s.groupCount},(_,i)=>s.groups[i]||{id:i+1,name:String(i+1)});return true}if(step===2){s.studentsText=$('#s-roster').value;return parseRoster(s.studentsText).students.length>0}if(step===3){s.ltId=$('#s-lt').value;s.lpId=$('#s-lp').value;s.studentPass=$('#s-stpass').value;s.ltPass=$('#s-lt-pass').value.trim();s.lpPass=$('#s-lp-pass').value.trim();if(s.studentPass.length<6||s.ltPass.length<6||(s.lpId&&s.lpPass.length<6))return false;s.groupLeaders={};$$('.s-gl').forEach(el=>{const g=el.dataset.g;s.groupLeaders[g]={...(s.groupLeaders[g]||{}),leaderId:el.value}});$$('.s-gd').forEach(el=>{const g=el.dataset.g;s.groupLeaders[g]={...(s.groupLeaders[g]||{}),deputyId:el.value}});$$('.s-gl-pass').forEach(el=>{const g=el.dataset.g;s.groupLeaders[g]={...(s.groupLeaders[g]||{}),leaderPass:el.value.trim()}});$$('.s-gd-pass').forEach(el=>{const g=el.dataset.g;s.groupLeaders[g]={...(s.groupLeaders[g]||{}),deputyPass:el.value.trim()}});for(const g of s.groups){if(!s.groupLeaders[g.id]?.leaderId||String(s.groupLeaders[g.id]?.leaderPass||'').length<6)return false;if(s.groupLeaders[g.id]?.deputyId&&String(s.groupLeaders[g.id]?.deputyPass||'').length<6)return false}const used=[s.ltId,s.lpId,...Object.values(s.groupLeaders).flatMap(x=>[x.leaderId,x.deputyId]).filter(Boolean)];const dup=used.filter((x,i)=>used.indexOf(x)!==i);if(dup.length)return false;return true}return true}
async function setupNext(){if(!collectSetupStep())return toast(state.setupStep===3?"Kiểm tra phân công: mỗi tổ cần tổ trưởng, không trùng người, và tài khoản HOCSINH cần mật khẩu. ":"Hãy nhập đủ thông tin.","err");if(state.setupStep<4){state.setupStep++;setupView()}else finishSetup()}
async function initFirebase(){try{const appApi=await import("https://www.gstatic.com/firebasejs/12.19.0/firebase-app.js");const authApi=await import("https://www.gstatic.com/firebasejs/12.19.0/firebase-auth.js");const dbApi=await import("https://www.gstatic.com/firebasejs/12.19.0/firebase-database.js");const app=appApi.initializeApp(FIREBASE_CONFIG),auth=authApi.getAuth(app),db=dbApi.getDatabase(app);fb={app,auth,db,authApi,dbApi,appApi};state.fbReady=true;let cfg;try{cfg=await dbGetWithTimeout(PATH.config)}catch(e){state.fbReady=false;state.syncError=e;throw new Error(e?.code==="PERMISSION_DENIED"?"Firebase Rules từ chối quyền đọc cấu hình lớp.":e?.message==="firebase-timeout"?"Hết thời gian chờ kết nối Firebase.":"Không thể đọc cấu hình Firebase.")}if(cfg?.exists()){state.config=cfg.val();authApi.onAuthStateChanged(auth,async user=>{try{if(!user){if(!state.profile)loginView();return}const p=await dbGet(`users/${user.uid}`);if(!p?.exists()){await authApi.signOut(auth);return loginView()}const v=p.val();if(v.active===false){await authApi.signOut(auth);toast("Tài khoản đã bị khóa.","err");return loginView()}state.user=user;state.profile={...v,uid:user.uid};state.tab="home";await syncAll();renderApp()}catch(e){console.warn(e);state.syncError=e;toast(e?.message||"Không tải được hồ sơ tài khoản.","err")}})}else setupView()}catch(e){console.warn(e);state.fbReady=false;state.syncError=e;showFirebaseError(e?.message||"Không thể kết nối Firebase.")}}
window.__scriptsLoaded=true;
function boot(){
  try{
    loadLocal();
    window.__tdBootRendered=true;
    window.__tdBootReady=true;
    setTimeout(()=>{initFirebase().catch(err=>{console.warn("Firebase init failed",err);state.fbReady=false;});},30);
  }catch(err){
    console.error(err);
    showBootError("Ứng dụng không thể khởi động. Hãy tải lại trang.");
  }
}
boot();
